<div class="page-heading dashboard-heading"><div><span class="eyebrow">IN-APP ONLY · FR-08</span><h1>Notifikasi</h1><p>Informasi pesanan dan perubahan status terbaru.</p></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="mark_all_read"><button class="btn btn-outline btn-small">Tandai semua dibaca</button></form></div><?php if(!$notifications): ?><div class="empty-state"><div class="empty-icon">♧</div><h3>Belum ada notifikasi</h3><p>Pemberitahuan transaksi akan muncul di sini.</p></div><?php else: ?><div class="notification-list"><?php foreach($notifications as $n): ?><article class="notification-card <?= $n['is_read']?'read':'unread' ?>"><div class="notification-dot"></div><div class="notification-body"><p><?= e($n['message']) ?></p><span class="muted small"><?= e(date('d M Y, H:i',strtotime($n['created_at']))) ?><?= $n['order_id']?' · Order #ORD-'.(int)$n['order_id']:'' ?></span></div><span class="notification-state"><?= $n['is_read']?'Dibaca':'Baru' ?></span></article><?php endforeach; ?></div><?php endif; ?>
